        $url = wp_get_attachment_image_url($custom_id, 'thumbnail');
        return '<img src="' . esc_url($url) . '" width="' . $size . '" height="' . $size . '" alt="' . esc_attr($channel) . '" loading="lazy" style="border-radius:50%;object-fit:cover;">';
